class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        best = 1
        subs_s = [s[i:j] for i in range(len(s)) for j in range(i + 1, len(s) + 1)]
        subs_t = [t[p:q] for p in range(len(t)) for q in range(p + 1, len(t) + 1)]
        for a in [""] + subs_s:
            for b in [""] + subs_t:
                if not a and not b:
                    continue
                c = a + b
                if c == c[::-1]:
                    best = max(best, len(c))
        return best

