class Solution {
public:
    int longestPalindrome(string s, string t) {
        int best = 1;
        int n = s.size(), m = t.size();
        auto isPal = [](const string& c) {
            int l = 0, r = c.size() - 1;
            while (l < r) if (c[l++] != c[r--]) return false;
            return true;
        };
        for (int i = 0; i <= n; i++)
            for (int j = i; j <= n; j++)
                for (int p = 0; p <= m; p++)
                    for (int q = p; q <= m; q++) {
                        if (i == j && p == q) continue;
                        string c = s.substr(i, j - i) + t.substr(p, q - p);
                        if (isPal(c)) best = max(best, (int)c.size());
                    }
        return best;
    }
};

