class Solution {
    public int longestPalindrome(String s, String t) {
        int best = 1, n = s.length(), m = t.length();
        for (int i = 0; i <= n; i++)
            for (int j = i; j <= n; j++)
                for (int p = 0; p <= m; p++)
                    for (int q = p; q <= m; q++) {
                        if (i == j && p == q) continue;
                        String c = s.substring(i, j) + t.substring(p, q);
                        boolean pal = true;
                        for (int l = 0, r = c.length() - 1; l < r; l++, r--)
                            if (c.charAt(l) != c.charAt(r)) { pal = false; break; }
                        if (pal) best = Math.max(best, c.length());
                    }
        return best;
    }
}

