var longestPalindrome = function(s, t) {
    let best = 1;
    const isPal = c => c === [...c].reverse().join('');
    const ss = [''];
    for (let i = 0; i < s.length; i++)
        for (let j = i + 1; j <= s.length; j++) ss.push(s.slice(i, j));
    const tt = [''];
    for (let p = 0; p < t.length; p++)
        for (let q = p + 1; q <= t.length; q++) tt.push(t.slice(p, q));
    for (const a of ss)
        for (const b of tt) {
            if (!a && !b) continue;
            const c = a + b;
            if (isPal(c)) best = Math.max(best, c.length);
        }
    return best;
};
